-- public.cellars_near(p_world uuid, p_x double precision, p_y double precision, p_range double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.cellars_near(p_world uuid, p_x double precision, p_y double precision, p_range double precision)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce((select jsonb_agg(jsonb_build_object('building', c.building, 'x', c.x, 'y', c.y, 'dug', c.dug)
                     order by c.y, c.x)
    from cellar_tile c
    where c.world_id = p_world
      and c.building in (select bt.building from building_tile bt
                          where bt.world_id = p_world
                            and bt.x between floor(p_x - p_range)::int - 1 and floor(p_x + p_range)::int + 1
                            and bt.y between floor(p_y - p_range)::int - 1 and floor(p_y + p_range)::int + 1
                            and greatest(abs(bt.x + 0.5 - p_x), abs(bt.y + 0.5 - p_y)) <= p_range)), '[]'::jsonb)
$function$
